create extension if not exists pgcrypto;
create table if not exists public.hub_user_data(user_id uuid primary key references auth.users(id) on delete cascade,payload jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.hub_ad_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,company_name text not null,contact_name text not null,email text not null,phone text,website text,budget text,message text not null,status text not null default 'received' check(status in('received','reviewing','accepted','declined')),created_at timestamptz not null default now());
create table if not exists public.hub_partner_applications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,organization text not null,contact_name text not null,email text not null,phone text,website text,proposal text not null,status text not null default 'received' check(status in('received','reviewing','accepted','declined')),created_at timestamptz not null default now());
create table if not exists public.hub_campaigns(id uuid primary key default gen_random_uuid(),title text not null,description text not null,destination_url text,image_url text,starts_at timestamptz,ends_at timestamptz,is_active boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.hub_plans(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,description text not null default '',amount_xof integer not null check(amount_xof>=100),duration_days integer not null check(duration_days>0),is_active boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.hub_payment_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_id uuid not null references public.hub_plans(id),amount_xof integer not null check(amount_xof>=100),currency text not null default 'XOF' check(currency='XOF'),merchant_transaction_id text not null unique,cinetpay_transaction_id text unique,payment_url text,notify_token text,status text not null default 'pending' check(status in('pending','paid','failed')),paid_at timestamptz,created_at timestamptz not null default now());
alter table public.hub_user_data enable row level security;
alter table public.hub_ad_requests enable row level security;
alter table public.hub_partner_applications enable row level security;
alter table public.hub_campaigns enable row level security;
alter table public.hub_plans enable row level security;
alter table public.hub_payment_orders enable row level security;
drop policy if exists hub_user_data_owner on public.hub_user_data;
create policy hub_user_data_owner on public.hub_user_data for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists hub_ads_owner_read on public.hub_ad_requests;
create policy hub_ads_owner_read on public.hub_ad_requests for select to authenticated using(auth.uid()=user_id);
drop policy if exists hub_ads_owner_insert on public.hub_ad_requests;
create policy hub_ads_owner_insert on public.hub_ad_requests for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists hub_partners_owner_read on public.hub_partner_applications;
create policy hub_partners_owner_read on public.hub_partner_applications for select to authenticated using(auth.uid()=user_id);
drop policy if exists hub_partners_owner_insert on public.hub_partner_applications;
create policy hub_partners_owner_insert on public.hub_partner_applications for insert to authenticated with check(auth.uid()=user_id);
drop policy if exists hub_campaigns_public_read on public.hub_campaigns;
create policy hub_campaigns_public_read on public.hub_campaigns for select to anon,authenticated using(is_active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()));
drop policy if exists hub_plans_public_read on public.hub_plans;
create policy hub_plans_public_read on public.hub_plans for select to anon,authenticated using(is_active=true);
grant select,insert,update,delete on public.hub_user_data to authenticated;
grant select,insert on public.hub_ad_requests to authenticated;
grant select,insert on public.hub_partner_applications to authenticated;
grant select on public.hub_campaigns,public.hub_plans to anon,authenticated;
